uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); h=r.parent/"helper"; (h/"Helper").mkdir(parents=True); (h/"lean-toolchain").write_text((T.ROOT/"lean/lean-toolchain").read_text()); (h/"lakefile.toml").write_text("name = \"helper\"\n\n[[lean_lib]]\nname = \"Helper\"\n"); (h/"Helper.lean").write_text("namespace Helper\n\nunsafe def lineOfImpl (path : String) (k : Nat) : String :=\n  match unsafeIO (IO.FS.readFile path) with\n  | .ok s => (s.splitOn \"\\n\")[k]!\n  | .error _ => \"\"\n\n@[implemented_by lineOfImpl]\ndef lineOf (_path : String) (_k : Nat) : String := \"\"\n\nend Helper\n"); (r/"lean/lakefile.toml").write_text(f"name = \"demo\"\n\n[[require]]\nname = \"helper\"\npath = \"{h}\"\n\n[[lean_lib]]\nname = \"Demo\"\nglobs = [\"Demo.*\"]\n"); (r/"lean/Demo/Defs.lean").write_text("import Helper\n\nnamespace Demo\n\ndef ref (n : Nat) : Bool := n < 3\n\n#guard Helper.lineOf \"Demo/Defs.lean\" 4 == \"def ref (n : Nat) : Bool := n < 3\" && ref 7 == ref 7\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"ref")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
